/**
 * Custom Field: Linking Action Buttons
 *
 * Renders two buttons: Cancel and Link.
 * Returns "true" (link) or "false" (cancel) as the field value.
 * Field ID in the form: link_email
 *
 * Params (set in custom field settings):
 *   - confirm_label: Label for the confirm button (default: "Link Account")
 */
function LinkingActionButtons(context) {
  const container = document.createElement("div");
  container.style.display = "flex";
  container.style.gap = "var(--spacing-2)";
  container.style.justifyContent = "center";
  container.style.marginTop = "var(--spacing-2)";

  let selectedValue = null;

  function handleAction(value) {
    selectedValue = value;
    context.form.goForward();
  }

  function buildButtons() {
    const { connection_type } = context.custom.getParams();
    const confirmLabel = "Connect with " + (connection_type || "Account");

    const cancelBtn = document.createElement("button");
    cancelBtn.type = "button";
    cancelBtn.classList.add("af-button", "af-button--secondary");
    cancelBtn.innerText = "Cancel";
    cancelBtn.onclick = function () {
      handleAction("false");
    };

    const confirmBtn = document.createElement("button");
    confirmBtn.type = "button";
    confirmBtn.classList.add("af-button", "af-button--primary");
    confirmBtn.innerText = confirmLabel;
    confirmBtn.onclick = function () {
      handleAction("true");
    };

    container.appendChild(cancelBtn);
    container.appendChild(confirmBtn);
  }

  return {
    init() {
      buildButtons();
      return container;
    },

    block() {
      const buttons = container.querySelectorAll("button");
      buttons.forEach(function (btn) {
        btn.disabled = true;
      });
    },

    unblock() {
      const buttons = container.querySelectorAll("button");
      buttons.forEach(function (btn) {
        btn.disabled = false;
      });
    },

    getValue() {
      if (selectedValue === null) {
        throw new Error("Please select an option to continue.");
      }
      return selectedValue;
    },
  };
}

